'use strict';
/**
 * Universal-key original-LP2 obstruction for a 4-dimensional F29 state
 * generated by the printed original page-15 4x4 integer square.
 *
 * State: x_(r+1) = M x_r over F29.
 * Display: C[r,c] = S[u_r,c](P[r,c]), u_r = first coordinate of x_r.
 * All 29*width S[u,c] are arbitrary independent 29-symbol bijections.
 * The entire unknown nonzero 4D IV space is exhausted projectively:
 * (29^4-1)/(29-1)=25,260 independent states. The IV=0 case is handled.
 *
 * Equality at two rows with the same u_r is conserved under EVERY secret
 * permutation. This test is independent of any candidate key recovery.
 *
 * Run: node sims/p15_matrix_allstate_square_collision.cjs
 * No third-party packages, no file writes, Windows Node.js 22 supported.
 *
 * @module p15_matrix_allstate_square_collision
 */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const ROOT=path.resolve(__dirname,'..');
const read=p=>fs.readFileSync(path.join(ROOT,p),'utf8');
const raw=read('resources/liber-primus/lp2-corpus.json');
const corpus=JSON.parse(raw);
const pages=corpus.pages.filter(p=>p.page<56&&p.indices.length);
const original=pages.flatMap(p=>p.indices);
assert.equal(original.length,12956);
assert.equal(pages.length,55);
assert.equal(81*81+80*80-5,original.length);
const M=[
  [3258,3222,3152,3038],
  [3278,3299,3298,2838],
  [3288,3294,3296,2472],
  [4516,1206,708,1820]
].map(row=>row.map(x=>x%29));
const transpose=A=>A[0].map((_,j)=>A.map(row=>row[j]));
const M0=M,M1=transpose(M);
const mod=x=>(x%29+29)%29;
/** GP29 transliteration for source-register controls. */
const tokens=corpus.translit.map((s,i)=>({s,i}))
  .sort((a,b)=>b.s.length-a.s.length);
/** @param {string} input @returns {number[]} */
function encodeGP(input){
  const out=[];
  for(let w of input.toUpperCase().match(/[A-Z]+/g)||[]){
    w=w.replace(/QU/g,'CW').replace(/V/g,'U').replace(/K/g,'C').replace(/Z/g,'S');
    for(let i=0;i<w.length;){
      const t=tokens.find(x=>w.startsWith(x.s,i));
      if(t){out.push(t.i);i+=t.s.length;}else i++;
    }
  }
  return out;
}
const SH=encodeGP(read('resources/control/shakespeare_first300k.txt'));
const GI=encodeGP(read('resources/control/gibran_prophet_58585.txt'));
assert.equal(SH.length,218800);
assert.equal(GI.length,63114);
/**
 * The finite group of nonzero scalings of a four-dimensional vector has
 * 28 members. Choose every unique projective direction once. A zero IV
 * leaves every plaintext rune unchanged, tested separately.
 * @returns {number[][]} 25,260 normalized IVs
 */
function projectiveStates(){
  const out=[];
  for(let first=0;first<4;first++){
    const count=29**(3-first);
    for(let value=0;value<count;value++){
      const x=Array(first).fill(0).concat(1);
      let left=value;
      for(let i=first+1;i<4;i++){
        x.push(left%29);
        left=Math.floor(left/29);
      }
      out.push(x);
    }
  }
  assert.equal(out.length,25260);
  assert.equal(new Set(out.map(x=>x.join(','))).size,out.length);
  return out;
}
const STATES=projectiveStates();
/** Row vector H[r] = e_0^T * M^r mod29. */
function projectionMatrix(matrix,n){
  let current=[1,0,0,0];
  const H=[];
  for(let r=0;r<n;r++){
    H.push(current);
    current=matrix[0].map((_,c)=>mod(current.reduce(
      (s,v,k)=>s+v*matrix[k][c],0)));
  }
  return H;
}
/** Column-major/row-major source block, with optional reversed row order. */
function at(r,c,n,axis,rev){
  const logicalRow=rev?n-1-r:r;
  return axis==='row'?logicalRow*n+c:c*n+logicalRow;
}
/** Actual projected state for any arbitrary IV. */
function sequence(H,x){
  return H.map(h=>mod(h[0]*x[0]+h[1]*x[1]+h[2]*x[2]+h[3]*x[3]));
}
/**
 * Pairwise weights are the EXACT count of observed same-symbol column pairs
 * in two rows. Secret S-boxes vanish from all same-state row-pair equalities.
 * @param {number[]} cipher
 * @param {number} width
 * @param {'row'|'column'} axis
 * @param {boolean} rev
 */
function pairWeights(cipher,width,axis,rev){
  const rows=[],later=[],matches=[],valid=[];
  for(let r=0;r<width;r++)for(let s=r+1;s<width;s++){
    let eq=0,pairs=0;
    for(let c=0;c<width;c++){
      const a=at(r,c,width,axis,rev);
      const b=at(s,c,width,axis,rev);
      if(a>=cipher.length||b>=cipher.length)continue;
      eq+=Number(cipher[a]===cipher[b]);
      pairs++;
    }
    rows.push(r);later.push(s);
    matches.push(eq);valid.push(pairs);
  }
  return {rows,later,matches,valid};
}
/** Key-free exact equalities among all positions sharing projected state. */
function scoreIV(u,pairs){
  let equal=0,total=0;
  for(let i=0;i<pairs.rows.length;i++)if(u[pairs.rows[i]]===u[pairs.later[i]]){
    equal+=pairs.matches[i];
    total+=pairs.valid[i];
  }
  assert(total>0);
  return {equal,total,rate:equal/total};
}
/** Exhaustively maximize the original equality ratio over all hidden IVs. */
function exhaustive(cipher,width,axis,rev,matrix){
  const pairs=pairWeights(cipher,width,axis,rev);
  const H=projectionMatrix(matrix,width);
  let best=null,minimum=null, evaluated=0;
  for(const iv of STATES){
    const observation=scoreIV(sequence(H,iv),pairs);
    if(!best||observation.rate>best.rate)best={...observation,iv};
    if(!minimum||observation.rate<minimum.rate)minimum={...observation,iv};
    evaluated++;
  }
  const zero=scoreIV(Array(width).fill(0),pairs);
  assert.equal(evaluated,25260);
  if(zero.rate>best.rate)best={...zero,iv:[0,0,0,0]};
  return {matrix:matrix===M0?'M':'MT',axis,reverseRows:rev,
    projectiveIVs:evaluated,zeroIV:zero,maximum:best,
    minimum,allSecretAlphabetsCovered:true};
}
/** Same equality invariant directly, without a pair table. */
function directScore(cipher,width,axis,rev,u){
  let matched=0,eligible=0;
  const buckets=Array.from({length:29},()=>[]);
  for(let r=0;r<width;r++)buckets[u[r]].push(r);
  for(let c=0;c<width;c++){
    const values=Array.from({length:29},()=>new Map());
    for(let r=0;r<width;r++){
      const i=at(r,c,width,axis,rev);
      if(i>=cipher.length)continue;
      const row=values[u[r]],x=cipher[i];
      matched+=row.get(x)||0;
      row.set(x,(row.get(x)||0)+1);
    }
    for(const row of values)for(const count of row.values())eligible+=0; // See next loop.
  }
  for(let i=0;i<width;i++)for(let j=i+1;j<width;j++)
    if(u[i]===u[j])for(let c=0;c<width;c++){
      const a=at(i,c,width,axis,rev),b=at(j,c,width,axis,rev);
      if(a<cipher.length&&b<cipher.length)eligible++;
    }
  return {equal:matched,total:eligible,rate:matched/eligible};
}
/** Seeded native-GP encryption with completely secret arbitrary S-box rows. */
function rng32(seed){
  let s=seed>>>0;
  return ()=>{s^=s<<13;s^=s>>>17;s^=s<<5;return s>>>0};
}
function plant(width,n,sourceOffset,seed){
  const random=rng32(seed);
  let x=Array.from({length:4},()=>random()%29);
  if(x.every(v=>v===0))x=[1,0,0,0];
  const u=sequence(projectionMatrix(M0,width),x);
  const plain=SH.slice(sourceOffset,sourceOffset+n);
  assert.equal(plain.length,n);
  const table=Array.from({length:29},()=>Array.from({length:width},()=>{
    const v=Array.from({length:29},(_,i)=>i);
    for(let i=28;i>0;i--){
      const j=random()%(i+1);
      [v[i],v[j]]=[v[j],v[i]];
    }
    return v;
  }));
  const inverse=table.map(row=>row.map(v=>{
    const inv=new Array(29);
    for(let i=0;i<29;i++)inv[v[i]]=i;
    assert.equal(new Set(v).size,29);
    return inv;
  }));
  const cipher=plain.map((value,i)=>table[u[Math.floor(i/width)]][i%width][value]);
  const decoded=cipher.map((value,i)=>inverse[u[Math.floor(i/width)]][i%width][value]);
  assert.deepEqual(decoded,plain);
  assert.deepEqual(decoded.map((value,i)=>table[u[Math.floor(i/width)]][i%width][value]),cipher);
  const input=directScore(plain,width,'row',false,u);
  const output=directScore(cipher,width,'row',false,u);
  assert.deepEqual(output,input);
  assert.deepEqual(scoreIV(u,pairWeights(cipher,width,'row',false)),output);
  return {width,positions:n,seed,hiddenInitialIV:x,
    arbitraryUnknownSBoxes:29*width,
    exactPlaintextInversion:n,exactCipherReencipher:n,
    sourceEqualityRate:output.rate,
    sourceEqualityPairs:output.equal,eligiblePairs:output.total};
}
function referenceSummary(source,width,length,iv,seed,limit=150){
  const H=projectionMatrix(M0,width),u=sequence(H,iv);
  const arr=[];
  for(let i=0;i<limit;i++){
    const start=source===SH?10000+i*100:i*100;
    const sample=source.slice(start,start+length);
    assert.equal(sample.length,length);
    const pairs=pairWeights(sample,width,'row',false);
    arr.push(scoreIV(u,pairs).rate);
  }
  arr.sort((a,b)=>a-b);
  return {windowCount:limit,min:arr[0],
    median:arr[Math.floor(limit/2)],max:arr.at(-1)};
}
function run(){
  const starts=Date.now();
  const squares=[{width:81,runes:original.slice(0,6561)},
    {width:80,runes:original.slice(6561)}];
  const authentic=[];
  for(const {width,runes}of squares){
    const exhaustiveModels=[];
    for(const matrix of [M0,M1])
      for(const axis of ['row','column'])
        for(const reverseRows of [false,true])
          exhaustiveModels.push(exhaustive(runes,width,axis,reverseRows,matrix));
    authentic.push({width,cipherRunes:runes.length,missingSquares:width*width-runes.length,
      variants:exhaustiveModels.length,
      widestAllowedOriginal:exhaustiveModels.reduce((a,b)=>
        a.maximum.rate>b.maximum.rate?a:b).maximum,
      perModel:exhaustiveModels.map(x=>({matrix:x.matrix,axis:x.axis,
        reverseRows:x.reverseRows,max:x.maximum,
        zeroIV:x.zeroIV,projectiveIVs:x.projectiveIVs}))});
  }
  const nativePlants=[
    plant(81,6561,100000,0x40161501),
    plant(80,6395,108000,0x40161502)];
  const reference=[];
  for(const {width,runes}of squares){
    const x=[3,3,0,1],so=referenceSummary(SH,width,runes.length,x,0,150);
    const gi=referenceSummary(GI,width,runes.length,x,0,150);
    reference.push({width,fixedIV:x,Shakespeare:so,Gibran:gi});
  }
  const overallMax=Math.max(...authentic.map(a=>a.widestAllowedOriginal.rate));
  for(const c of reference)for(const source of [c.Shakespeare,c.Gibran])
    assert(source.min>overallMax,
      'Selected native-GP positive unexpectedly has original-like collisions');
  return {
    status:'Exact unknown-IV, arbitrary-29!-S-box no-go conditional on native GP prose',
    model:'C[r,c]=S[(e0^T*M^r*x0),c](P[r,c]); all S any independent 29-way permutation',
    originalMatrix:M0,modulus:29,
    originalUnsolvedRunes:original.length,
    nonzeroProjectiveIVs:STATES.length,
    trueIVsCovered:29**4,
    original:authentic,
    nativeSourceOriginalShapedPlants:nativePlants,
    sourceControls:reference,
    originalUpperRate:overallMax,
    corpusSHA256:crypto.createHash('sha256').update(raw).digest('hex'),
    elapsedMilliseconds:Date.now()-starts,
    limitation:'The two square layouts and direct GP-literary plaintext are hypotheses. Other state projections, evolving row keys and binary intermediates remain open.'
  };
}
if(require.main===module)console.log(JSON.stringify(run(),null,2));
module.exports={M0,M1,projectiveStates,projectionMatrix,pairWeights,
  scoreIV,exhaustive,directScore,plant,run};
